// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        feeRate = uint16(bound(feeRate, 1, 5_000));
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useOracle, payRoy) {
            assertTrue(c.feeRate() == feeRate, "feeRate must equal initialized value");
        } catch {
            assertTrue(true);
        }
    }
}
